use std::fs

fn digit_val(c: char) -> int {
    let n = c as int
    if n >= 65 && n <= 90 { n - 55 } else { n - 48 }
}

fn digit_char(d: int) -> char {
    if d < 10 { (d + 48) as u8 as char } else { (d + 55) as u8 as char }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() < 3 {
            continue
        }
        let from = parts[1].parse::<int>().unwrap_or(10)
        let to = parts[2].parse::<int>().unwrap_or(10)
        let mut v = 0
        for c in parts[0].chars() {
            v = v * from + digit_val(c)
        }
        if v == 0 {
            println("0")
            continue
        }
        let mut out: Vec<char> = []
        while v > 0 {
            out.push(digit_char(v % to))
            v = v / to
        }
        out.reverse()
        let mut s = ""
        for c in out {
            s = s + c.to_string()
        }
        println(s)
    }
}

